 if(needsMedKit()){target=world.shop.table.position;text='Purchase a med kit';sub='Equipment Shop · $250 · Required before departure';stage='PREPARATION';}
 else if(isNight()&&!s.nightEquipped){target=world.shop.table.position;text=save.inventory?.carbine?'Equip your semi-auto':'Buy the semi-auto';sub='Equipment Shop · E to open shop';stage='NIGHT PREPARATION';}
 else if(packAlive().length){target=markedAnimal.root.position;text='Defend yourself';sub=packAlive().length+' wolves remaining · One shot each · R reload';stage='WOLF AMBUSH';}
 else if(training&&(lessonStep===1||lessonStep===2)){target=parkingPoint(false);text='Stop inside the gold circle';sub='Hold SPACE to brake completely.';}
 else if(training&&lessonStep===0){target=world.truck.position;text='Enter the truck';sub='Walk to the driver’s door · E';}
 else if(training&&(lessonStep===8||lessonStep===9)){target=parkingPoint(true);text='Return to the station circle';sub='Stop completely before leaving the truck.';}
 else if(s.carry){target=world.truck.position;text='Load at the tailgate';sub='Hold E at the rear of the truck';stage='RECOVERY';}
 else if(s.sold+s.cargo.length>=mission.count){target=world.desk.position;text='Return and sell your harvest';sub='Park at the station · Hold E at the forest desk';stage='RETURN & SELL';}
 else if(markedAnimal){target=markedAnimal.root.position;text=markedAnimal.alerted?(mission.species==='goose'?'Flock airborne — track your target':mission.species==='bear'?'Bear charging — keep moving':mission.species==='lion'?'Lioness charging — keep moving':mission.species==='rhino'?'Rhinos charging — keep moving':mission.species==='alligator'?'Alligator charging — keep moving':mission.species==='boar'?'Boar charging — keep moving':'Animal alerted — do not lose it'):mission.region;sub=markedAnimal.alerted?(mission.species==='goose'?'Lead the bird · Click to fire · R reload':['boar','alligator','rhino','lion','bear'].includes(mission.species)?'Sidestep the rush · Reload while it turns':'Escape boundary 150 m from its feeding ground'):`Harvest ${s.kills} / ${mission.count} · ${mission.species==='bear'?'Within 60 m · Five hits':mission.species==='lion'?'Within 100 m · Four hits':mission.species==='rhino'?'Within 48 m · Five hits':mission.species==='alligator'?'Get within 60 m · Two hits':'Hold SHIFT to scope'}`;if(mission.limit)sub+=` · ${formatTime(Math.max(0,mission.limit-s.huntElapsed))}`;}
 else{const dead=animals.find(a=>a.dead&&!a.collected&&!a.ambush);target=dead?.root.position||world.truck.position;text=dead?'Recover your harvest':'Return to your truck';sub=dead?'Hold E beside the animal':'E · take the wheel';stage='RECOVERY';}
