 drawMiniMap();
 hover=interaction();$('prompt').classList.toggle('visible',!!hover&&!s.aim);if(hover){$('promptText').textContent=hover.title;$('promptSub').textContent=hover.sub;$('promptKey').textContent=hover.hold?'E':'E';}$('holdProgress').style.width=hover?.hold?`${clamp(s.hold/hover.hold,0,1)*170}px`:'0';show('ammoHud',!s.driving);show('vehicleHud',s.driving);$('healthLabel').textContent=Math.max(0,Math.round(s.health));$('healthBar').style.width=`${Math.max(0,s.health)}%`;$('clockLabel').textContent='TIME LIMIT '+formatTime(Math.max(0,(mission.limit||900)-(training?s.elapsed:s.huntElapsed)));$('aimDot').style.opacity=s.aim||s.driving?'0':'1';world.desk.userData.updateLedger?.(mission,s,save);
