function parkingPoint(home){const p=home?[-3,7]:INTRO.parking;return new T.Vector3(p[0],height(...p)+.08,p[1]);}
const parkingRing=new T.Mesh(new T.RingGeometry(6.7,7.1,80),new T.MeshBasicMaterial({color:0xffd27d,side:T.DoubleSide,transparent:true,opacity:.85,depthTest:false}));parkingRing.rotation.x=-Math.PI/2;parkingRing.renderOrder=3;parkingRing.visible=false;scene.add(parkingRing);
