 const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(positions,3));const material=new T.PointsMaterial({color:animalHit?0x866e52:0xa4967e,size:animalHit?.025:.08,transparent:true,opacity:.45,depthWrite:false});material.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('vec4 diffuseColor = vec4( diffuse, opacity );','float d=length(gl_PointCoord-.5)*2.; if(d>1.)discard;vec4 diffuseColor = vec4(diffuse,opacity*(1.-d));');};
